/*!
 * Three.js Local 3D Lit-Shader, Depth-Sorted Mesh & Particle Engine (Singularity Avant-Garde Build)
 * Exposes standard THREE namespace with full 3D face shading, rim lighting, specular chrome,
 * depth sorting (Painter's algorithm), glowing wireframes, orbital HUD rings, and particle fields.
 */
(function (global) {
  'use strict';

  class Color {
    constructor(hex) {
      this.r = 0.55; this.g = 0.36; this.b = 0.96;
      if (hex !== undefined) this.set(hex);
    }
    set(val) {
      if (val instanceof Color) {
        this.r = val.r; this.g = val.g; this.b = val.b;
        return this;
      }
      if (typeof val === 'number') {
        this.r = ((val >> 16) & 255) / 255;
        this.g = ((val >> 8) & 255) / 255;
        this.b = (val & 255) / 255;
        return this;
      }
      if (typeof val === 'string') {
        let s = val.trim().replace(/^#/, '');
        if (s.length === 3) s = s[0] + s[0] + s[1] + s[1] + s[2] + s[2];
        const n = parseInt(s, 16);
        if (!Number.isNaN(n)) {
          this.r = ((n >> 16) & 255) / 255;
          this.g = ((n >> 8) & 255) / 255;
          this.b = (n & 255) / 255;
        }
      }
      return this;
    }
    toRgba(alpha) {
      const r = Math.max(0, Math.min(255, Math.round(this.r * 255)));
      const g = Math.max(0, Math.min(255, Math.round(this.g * 255)));
      const b = Math.max(0, Math.min(255, Math.round(this.b * 255)));
      return `rgba(${r},${g},${b},${alpha == null ? 1 : alpha})`;
    }
    toShadedRgba(shade, spec, rim, rimCol, alpha) {
      const rc = rimCol || this;
      const r = Math.max(0, Math.min(255, Math.round((this.r * shade + rc.r * rim + spec) * 255)));
      const g = Math.max(0, Math.min(255, Math.round((this.g * shade + rc.g * rim + spec) * 255)));
      const b = Math.max(0, Math.min(255, Math.round((this.b * shade + rc.b * rim + spec) * 255)));
      return `rgba(${r},${g},${b},${alpha == null ? 1 : alpha})`;
    }
  }

  class Vector3 {
    constructor(x = 0, y = 0, z = 0) {
      this.x = x; this.y = y; this.z = z;
    }
    set(x, y, z) { this.x = x; this.y = y; this.z = z; return this; }
    copy(v) { this.x = v.x; this.y = v.y; this.z = v.z; return this; }
    clone() { return new Vector3(this.x, this.y, this.z); }
    add(v) { this.x += v.x; this.y += v.y; this.z += v.z; return this; }
    subVectors(a, b) { this.x = a.x - b.x; this.y = a.y - b.y; this.z = a.z - b.z; return this; }
    crossVectors(a, b) {
      const ax = a.x, ay = a.y, az = a.z;
      const bx = b.x, by = b.y, bz = b.z;
      this.x = ay * bz - az * by;
      this.y = az * bx - ax * bz;
      this.z = ax * by - ay * bx;
      return this;
    }
    normalize() {
      const len = Math.hypot(this.x, this.y, this.z) || 1;
      this.x /= len; this.y /= len; this.z /= len;
      return this;
    }
    multiplyScalar(s) { this.x *= s; this.y *= s; this.z *= s; return this; }
  }

  class Float32BufferAttribute {
    constructor(array, itemSize) {
      this.array = array instanceof Float32Array ? array : new Float32Array(array);
      this.itemSize = itemSize || 3;
      this.count = Math.floor(this.array.length / this.itemSize);
      this.needsUpdate = true;
    }
  }

  class BufferGeometry {
    constructor() {
      this.attributes = {};
      this.index = null;
      this._edges = null;
    }
    setAttribute(name, attr) {
      this.attributes[name] = attr;
      this._edges = null;
      return this;
    }
    setIndex(indices) {
      this.index = indices instanceof Uint16Array ? indices : new Uint16Array(indices);
      this._edges = null;
      return this;
    }
    dispose() {}
  }

  function extractWireframeEdges(geometry) {
    if (geometry._edges) return geometry._edges;
    const pos = geometry.attributes.position;
    if (!pos) return new Uint16Array(0);
    const edgeSet = new Set();
    const edges = [];
    const addEdge = (a, b) => {
      const min = a < b ? a : b;
      const max = a < b ? b : a;
      const key = (min << 16) | max;
      if (!edgeSet.has(key)) {
        edgeSet.add(key);
        edges.push(min, max);
      }
    };
    if (geometry.index && geometry.index.length >= 3) {
      const idx = geometry.index;
      for (let i = 0; i < idx.length; i += 3) {
        addEdge(idx[i], idx[i + 1]);
        addEdge(idx[i + 1], idx[i + 2]);
        addEdge(idx[i + 2], idx[i]);
      }
    } else {
      for (let i = 0; i + 2 < pos.count; i += 3) {
        addEdge(i, i + 1);
        addEdge(i + 1, i + 2);
        addEdge(i + 2, i);
      }
    }
    geometry._edges = new Uint16Array(edges);
    return geometry._edges;
  }

  class WireframeGeometry extends BufferGeometry {
    constructor(sourceGeo) {
      super();
      if (!sourceGeo || !sourceGeo.attributes.position) return;
      const srcPos = sourceGeo.attributes.position.array;
      const edges = extractWireframeEdges(sourceGeo);
      const out = new Float32Array(edges.length * 3);
      for (let i = 0; i < edges.length; i++) {
        const vi = edges[i] * 3;
        out[i * 3] = srcPos[vi];
        out[i * 3 + 1] = srcPos[vi + 1];
        out[i * 3 + 2] = srcPos[vi + 2];
      }
      this.setAttribute('position', new Float32BufferAttribute(out, 3));
    }
  }

  class IcosahedronGeometry extends BufferGeometry {
    constructor(radius = 1, detail = 0) {
      super();
      const t = (1 + Math.sqrt(5)) / 2;
      const rawVerts = [
        [-1,  t,  0], [ 1,  t,  0], [-1, -t,  0], [ 1, -t,  0],
        [ 0, -1,  t], [ 0,  1,  t], [ 0, -1, -t], [ 0,  1, -t],
        [ t,  0, -1], [ t,  0,  1], [-t,  0, -1], [-t,  0,  1]
      ].map(([x, y, z]) => {
        const len = Math.hypot(x, y, z) || 1;
        return [x / len, y / len, z / len];
      });
      let faces = [
        [0, 11, 5], [0, 5, 1], [0, 1, 7], [0, 7, 10], [0, 10, 11],
        [1, 5, 9], [5, 11, 4], [11, 10, 2], [10, 7, 6], [7, 1, 8],
        [3, 9, 4], [3, 4, 2], [3, 2, 6], [3, 6, 8], [3, 8, 9],
        [4, 9, 5], [2, 4, 11], [6, 2, 10], [8, 6, 7], [9, 8, 1]
      ];
      const midCache = new Map();
      const getMid = (a, b) => {
        const key = a < b ? `${a}_${b}` : `${b}_${a}`;
        if (midCache.has(key)) return midCache.get(key);
        const va = rawVerts[a], vb = rawVerts[b];
        const mx = (va[0] + vb[0]) * 0.5;
        const my = (va[1] + vb[1]) * 0.5;
        const mz = (va[2] + vb[2]) * 0.5;
        const len = Math.hypot(mx, my, mz) || 1;
        const idx = rawVerts.length;
        rawVerts.push([mx / len, my / len, mz / len]);
        midCache.set(key, idx);
        return idx;
      };
      const steps = Math.min(2, Math.max(0, detail | 0));
      for (let s = 0; s < steps; s++) {
        const nextFaces = [];
        for (let i = 0; i < faces.length; i++) {
          const [a, b, c] = faces[i];
          const ab = getMid(a, b);
          const bc = getMid(b, c);
          const ca = getMid(c, a);
          nextFaces.push([a, ab, ca], [b, bc, ab], [c, ca, bc], [ab, bc, ca]);
        }
        faces = nextFaces;
      }
      const pos = new Float32Array(rawVerts.length * 3);
      for (let i = 0; i < rawVerts.length; i++) {
        pos[i * 3] = rawVerts[i][0] * radius;
        pos[i * 3 + 1] = rawVerts[i][1] * radius;
        pos[i * 3 + 2] = rawVerts[i][2] * radius;
      }
      const indices = new Uint16Array(faces.length * 3);
      for (let i = 0; i < faces.length; i++) {
        indices[i * 3] = faces[i][0];
        indices[i * 3 + 1] = faces[i][1];
        indices[i * 3 + 2] = faces[i][2];
      }
      this.setAttribute('position', new Float32BufferAttribute(pos, 3));
      this.setIndex(indices);
    }
  }

  class OctahedronGeometry extends BufferGeometry {
    constructor(radius = 1) {
      super();
      const r = radius;
      const pos = new Float32Array([
        r, 0, 0,  -r, 0, 0,  0, r, 0,  0, -r, 0,  0, 0, r,  0, 0, -r
      ]);
      const indices = new Uint16Array([
        0, 2, 4,  0, 4, 3,  0, 3, 5,  0, 5, 2,
        1, 2, 5,  1, 5, 3,  1, 3, 4,  1, 4, 2
      ]);
      this.setAttribute('position', new Float32BufferAttribute(pos, 3));
      this.setIndex(indices);
    }
  }

  class BoxGeometry extends BufferGeometry {
    constructor(w = 1, h = 1, d = 1) {
      super();
      const x = w * 0.5, y = h * 0.5, z = d * 0.5;
      const pos = new Float32Array([
        -x, -y,  z,   x, -y,  z,   x,  y,  z,  -x,  y,  z,
        -x, -y, -z,   x, -y, -z,   x,  y, -z,  -x,  y, -z
      ]);
      const indices = new Uint16Array([
        0, 1, 2, 0, 2, 3,  1, 5, 6, 1, 6, 2,
        5, 4, 7, 5, 7, 6,  4, 0, 3, 4, 3, 7,
        3, 2, 6, 3, 6, 7,  4, 5, 1, 4, 1, 0
      ]);
      this.setAttribute('position', new Float32BufferAttribute(pos, 3));
      this.setIndex(indices);
    }
  }

  class TorusKnotGeometry extends BufferGeometry {
    constructor(radius = 1, tube = 0.3, tubularSegments = 64, radialSegments = 8, p = 2, q = 3) {
      super();
      const tubSeg = Math.max(16, Math.min(120, tubularSegments | 0));
      const radSeg = Math.max(4, Math.min(16, radialSegments | 0));
      const verts = [];
      const indices = [];

      const getPointOnCurve = (u, out) => {
        const cu = Math.cos(u), su = Math.sin(u);
        const quOverP = (q / p) * u;
        const cs = Math.cos(quOverP);
        out.x = radius * (2 + cs) * 0.5 * cu;
        out.y = radius * (2 + cs) * su * 0.5;
        out.z = radius * Math.sin(quOverP) * 0.5;
      };

      const P1 = new Vector3();
      const P2 = new Vector3();
      const T = new Vector3();
      const N = new Vector3();
      const B = new Vector3();

      for (let i = 0; i <= tubSeg; i++) {
        const u = (i / tubSeg) * p * Math.PI * 2;
        getPointOnCurve(u, P1);
        getPointOnCurve(u + 0.01, P2);
        T.subVectors(P2, P1);
        N.set(P2.x + P1.x, P2.y + P1.y, P2.z + P1.z);
        B.crossVectors(T, N).normalize();
        N.crossVectors(B, T).normalize();

        for (let j = 0; j <= radSeg; j++) {
          const v = (j / radSeg) * Math.PI * 2;
          const cx = -tube * Math.cos(v);
          const cy = tube * Math.sin(v);
          verts.push(
            P1.x + (cx * N.x + cy * B.x),
            P1.y + (cx * N.y + cy * B.y),
            P1.z + (cx * N.z + cy * B.z)
          );
        }
      }

      for (let j = 1; j <= tubSeg; j++) {
        for (let i = 1; i <= radSeg; i++) {
          const a = (radSeg + 1) * (j - 1) + (i - 1);
          const b = (radSeg + 1) * j + (i - 1);
          const c = (radSeg + 1) * j + i;
          const d = (radSeg + 1) * (j - 1) + i;
          indices.push(a, b, d, b, c, d);
        }
      }

      this.setAttribute('position', new Float32BufferAttribute(new Float32Array(verts), 3));
      this.setIndex(new Uint16Array(indices));
    }
  }

  class RingGeometry extends BufferGeometry {
    constructor(innerRadius = 1, outerRadius = 1.2, thetaSegments = 48) {
      super();
      const segs = Math.max(12, thetaSegments | 0);
      const verts = [];
      const indices = [];
      for (let i = 0; i <= segs; i++) {
        const a = (i / segs) * Math.PI * 2;
        const c = Math.cos(a), s = Math.sin(a);
        verts.push(c * innerRadius, s * innerRadius, 0);
        verts.push(c * outerRadius, s * outerRadius, 0);
      }
      for (let i = 0; i < segs; i++) {
        const b = i * 2;
        indices.push(b, b + 1, b + 2, b + 1, b + 3, b + 2);
      }
      this.setAttribute('position', new Float32BufferAttribute(new Float32Array(verts), 3));
      this.setIndex(new Uint16Array(indices));
    }
  }

  class Material {
    constructor(opts = {}) {
      this.color = new Color(opts.color !== undefined ? opts.color : 0x8b5cf6);
      this.rimColor = new Color(opts.rimColor !== undefined ? opts.rimColor : (opts.color !== undefined ? opts.color : 0xff00a0));
      this.edgeColor = opts.edgeColor !== undefined ? new Color(opts.edgeColor) : null;
      this.opacity = opts.opacity !== undefined ? opts.opacity : 1.0;
      this.fillOpacity = opts.fillOpacity !== undefined ? opts.fillOpacity : 0.42;
      this.transparent = !!opts.transparent;
      this.wireframe = !!opts.wireframe;
      this.flatShading = opts.flatShading !== undefined ? !!opts.flatShading : true;
      this.metallic = opts.metallic !== undefined ? opts.metallic : 0.55;
      this.glow = opts.glow !== undefined ? opts.glow : 0;
      this.size = opts.size !== undefined ? opts.size : 2.2;
      this.linewidth = opts.linewidth !== undefined ? opts.linewidth : 1.2;
    }
    dispose() {}
  }

  class MeshBasicMaterial extends Material {}
  class LineBasicMaterial extends Material {}
  class PointsMaterial extends Material {}

  class Object3D {
    constructor() {
      this.position = new Vector3(0, 0, 0);
      this.rotation = new Vector3(0, 0, 0);
      this.scale = new Vector3(1, 1, 1);
      this.children = [];
      this.parent = null;
      this.visible = true;
      this.userData = {};
    }
    add(...objs) {
      objs.forEach(o => {
        if (!o) return;
        if (o.parent) o.parent.remove(o);
        o.parent = this;
        this.children.push(o);
      });
      return this;
    }
    remove(...objs) {
      objs.forEach(o => {
        const idx = this.children.indexOf(o);
        if (idx !== -1) {
          o.parent = null;
          this.children.splice(idx, 1);
        }
      });
      return this;
    }
    clear() {
      this.children.forEach(c => { c.parent = null; });
      this.children.length = 0;
      return this;
    }
  }

  class Scene extends Object3D {
    constructor() {
      super();
      this.isScene = true;
      this.background = null;
    }
  }

  class Group extends Object3D {}

  class Mesh extends Object3D {
    constructor(geometry, material) {
      super();
      this.geometry = geometry || new BufferGeometry();
      this.material = material || new MeshBasicMaterial();
      this.isMesh = true;
    }
  }

  class LineSegments extends Object3D {
    constructor(geometry, material) {
      super();
      this.geometry = geometry || new BufferGeometry();
      this.material = material || new LineBasicMaterial();
      this.isLineSegments = true;
    }
  }

  class Points extends Object3D {
    constructor(geometry, material) {
      super();
      this.geometry = geometry || new BufferGeometry();
      this.material = material || new PointsMaterial();
      this.isPoints = true;
    }
  }

  class GridHelper extends LineSegments {
    constructor(size = 10, divisions = 10, color1 = 0x8b5cf6, color2 = 0x334155) {
      const step = size / divisions;
      const half = size * 0.5;
      const verts = [];
      for (let i = 0, k = -half; i <= divisions; i++, k += step) {
        verts.push(-half, 0, k, half, 0, k);
        verts.push(k, 0, -half, k, 0, half);
      }
      const geo = new BufferGeometry();
      geo.setAttribute('position', new Float32BufferAttribute(new Float32Array(verts), 3));
      super(geo, new LineBasicMaterial({ color: color1 !== undefined ? color1 : color2, opacity: 0.42, transparent: true, linewidth: 1.25 }));
    }
  }

  class PerspectiveCamera extends Object3D {
    constructor(fov = 60, aspect = 1, near = 0.1, far = 1000) {
      super();
      this.fov = fov;
      this.aspect = aspect;
      this.near = near;
      this.far = far;
      this.lookAtTarget = new Vector3(0, 0, 0);
    }
    lookAt(x, y, z) {
      if (x instanceof Vector3) this.lookAtTarget.copy(x);
      else this.lookAtTarget.set(x || 0, y || 0, z || 0);
    }
    updateProjectionMatrix() {}
  }

  class Clock {
    constructor() {
      this.startTime = (typeof performance !== 'undefined' ? performance.now() : Date.now()) * 0.001;
      this.oldTime = this.startTime;
    }
    getElapsedTime() {
      const now = (typeof performance !== 'undefined' ? performance.now() : Date.now()) * 0.001;
      return now - this.startTime;
    }
    getDelta() {
      const now = (typeof performance !== 'undefined' ? performance.now() : Date.now()) * 0.001;
      const d = now - this.oldTime;
      this.oldTime = now;
      return d;
    }
  }

  function transformVertex(vx, vy, vz, obj, parentRotX, parentRotY, parentRotZ, parentPosX, parentPosY, parentPosZ) {
    let x = vx * obj.scale.x;
    let y = vy * obj.scale.y;
    let z = vz * obj.scale.z;

    const rx = obj.rotation.x + parentRotX;
    const ry = obj.rotation.y + parentRotY;
    const rz = obj.rotation.z + parentRotZ;

    if (rx !== 0) {
      const cx = Math.cos(rx), sx = Math.sin(rx);
      const y1 = y * cx - z * sx;
      const z1 = y * sx + z * cx;
      y = y1; z = z1;
    }
    if (ry !== 0) {
      const cy = Math.cos(ry), sy = Math.sin(ry);
      const x1 = x * cy + z * sy;
      const z1 = -x * sy + z * cy;
      x = x1; z = z1;
    }
    if (rz !== 0) {
      const cz = Math.cos(rz), sz = Math.sin(rz);
      const x1 = x * cz - y * sz;
      const y1 = x * sz + y * cz;
      x = x1; y = y1;
    }

    return {
      x: x + obj.position.x + parentPosX,
      y: y + obj.position.y + parentPosY,
      z: z + obj.position.z + parentPosZ
    };
  }

  // 主光源方向 (归一化)
  const LIGHT_DIR = { x: 0.45, y: 0.65, z: 0.61 };

  class WebGLRenderer {
    constructor(opts = {}) {
      this.domElement = opts.canvas || (typeof document !== 'undefined' ? document.createElement('canvas') : {});
      this.width = 800;
      this.height = 600;
      this.pixelRatio = 1;
      this._ctx = null;
      const isJsdom = typeof navigator !== 'undefined' && /jsdom/i.test(navigator.userAgent || '');
      try {
        if (!isJsdom && this.domElement && typeof this.domElement.getContext === 'function') {
          this._ctx = this.domElement.getContext('2d');
        }
      } catch (e) {
        this._ctx = null;
      }
    }
    setPixelRatio(r) {
      this.pixelRatio = Math.min(2, Math.max(1, r || 1));
    }
    setSize(w, h) {
      this.width = Math.max(1, w | 0);
      this.height = Math.max(1, h | 0);
      if (this.domElement && this.domElement.style) {
        this.domElement.width = this.width * this.pixelRatio;
        this.domElement.height = this.height * this.pixelRatio;
      }
    }
    clear() {
      if (!this._ctx) return;
      this._ctx.clearRect(0, 0, this.width * this.pixelRatio, this.height * this.pixelRatio);
    }
    render(scene, camera) {
      const ctx = this._ctx;
      if (!ctx || !scene || !camera) return;
      const pr = this.pixelRatio;
      const W = this.width * pr;
      const H = this.height * pr;
      const halfW = W * 0.5;
      const halfH = H * 0.5;

      ctx.clearRect(0, 0, W, H);

      // 绘制自定义舞台天幕背景特效 (如 Cyber 合成波落日、Acid 十字准星、Abyss 星云引力场)
      if (scene.userData && typeof scene.userData.customBackdrop === 'function') {
        ctx.save();
        scene.userData.customBackdrop(ctx, W, H, pr);
        ctx.restore();
      }

      const fovRad = ((camera.fov || 58) * Math.PI) / 180;
      const focal = halfH / Math.tan(fovRad * 0.5);

      const camX = camera.position.x;
      const camY = camera.position.y;
      const camZ = camera.position.z || 6;

      const yaw = -camX * 0.14;
      const pitch = camY * 0.14;
      const cy = Math.cos(yaw), sy = Math.sin(yaw);
      const cp = Math.cos(pitch), sp = Math.sin(pitch);

      const project = (wx, wy, wz) => {
        const dx = wx - camX;
        const dy = wy - camY;
        const dz = wz - camZ;

        const rx = dx * cy - dz * sy;
        const rz1 = dx * sy + dz * cy;
        const ry = dy * cp - rz1 * sp;
        const rz = dy * sp + rz1 * cp;

        const depth = -rz;
        if (depth <= 0.15) return null;
        const scale = focal / depth;
        return {
          sx: halfW + rx * scale,
          sy: halfH - ry * scale,
          wx, wy, wz,
          depth,
          scale
        };
      };

      const renderNode = (node, pRx, pRy, pRz, pPx, pPy, pPz) => {
        if (!node || !node.visible) return;
        const curRx = pRx + (node.isScene ? 0 : node.rotation.x);
        const curRy = pRy + (node.isScene ? 0 : node.rotation.y);
        const curRz = pRz + (node.isScene ? 0 : node.rotation.z);
        const curPx = pPx + (node.isScene ? 0 : node.position.x);
        const curPy = pPy + (node.isScene ? 0 : node.position.y);
        const curPz = pPz + (node.isScene ? 0 : node.position.z);

        const geo = node.geometry;
        const mat = node.material;
        if (geo && geo.attributes && geo.attributes.position && mat) {
          const posArr = geo.attributes.position.array;
          const baseAlpha = mat.opacity != null ? mat.opacity : 1;
          const col = mat.color || new Color(0x8b5cf6);
          const rimCol = mat.rimColor || col;

          if (node.isPoints) {
            const ptSize = (mat.size || 2.2) * pr;
            for (let i = 0; i < posArr.length; i += 3) {
              const w = transformVertex(posArr[i], posArr[i + 1], posArr[i + 2], node, pRx, pRy, pRz, pPx, pPy, pPz);
              const p = project(w.x, w.y, w.z);
              if (!p) continue;
              const depthFade = Math.max(0.12, Math.min(1, 8.2 / (p.depth + 2.0)));
              const r = Math.max(0.8, (ptSize * 4.2) / (p.depth + 1.4));
              const useRim = (i % 9 === 0);
              ctx.fillStyle = (useRim ? rimCol : col).toRgba(baseAlpha * depthFade);
              ctx.beginPath();
              ctx.arc(p.sx, p.sy, r, 0, Math.PI * 2);
              ctx.fill();
            }
          } else if (node.isLineSegments) {
            ctx.save();
            if (mat.glow > 0) {
              ctx.shadowColor = col.toRgba(0.85);
              ctx.shadowBlur = mat.glow * pr;
            }
            ctx.lineWidth = (mat.linewidth || 1.2) * pr;
            ctx.strokeStyle = col.toRgba(baseAlpha);
            ctx.beginPath();
            for (let i = 0; i + 5 < posArr.length; i += 6) {
              const w1 = transformVertex(posArr[i], posArr[i + 1], posArr[i + 2], node, pRx, pRy, pRz, pPx, pPy, pPz);
              const w2 = transformVertex(posArr[i + 3], posArr[i + 4], posArr[i + 5], node, pRx, pRy, pRz, pPx, pPy, pPz);
              const p1 = project(w1.x, w1.y, w1.z);
              const p2 = project(w2.x, w2.y, w2.z);
              if (!p1 || !p2) continue;
              ctx.moveTo(p1.sx, p1.sy);
              ctx.lineTo(p2.sx, p2.sy);
            }
            ctx.stroke();
            ctx.restore();
          } else if (node.isMesh) {
            const edges = extractWireframeEdges(geo);
            const vertCount = geo.attributes.position.count;
            const projCache = new Array(vertCount);
            for (let v = 0; v < vertCount; v++) {
              const vi = v * 3;
              const w = transformVertex(posArr[vi], posArr[vi + 1], posArr[vi + 2], node, pRx, pRy, pRz, pPx, pPy, pPz);
              projCache[v] = project(w.x, w.y, w.z);
            }

            // 真实 3D 光照着色与画家算法深度排序 (Painter's Algorithm + Lambert/Rim/Specular Shading)
            if (!mat.wireframe && geo.index) {
              const idx = geo.index;
              const drawTris = [];
              for (let i = 0; i < idx.length; i += 3) {
                const p0 = projCache[idx[i]];
                const p1 = projCache[idx[i + 1]];
                const p2 = projCache[idx[i + 2]];
                if (!p0 || !p1 || !p2) continue;
                const cross = (p1.sx - p0.sx) * (p2.sy - p0.sy) - (p1.sy - p0.sy) * (p2.sx - p0.sx);
                if (cross < 0) continue; // 背面剔除

                // 计算世界空间三角形法线
                const ux = p1.wx - p0.wx, uy = p1.wy - p0.wy, uz = p1.wz - p0.wz;
                const vx = p2.wx - p0.wx, vy = p2.wy - p0.wy, vz = p2.wz - p0.wz;
                let nx = uy * vz - uz * vy;
                let ny = uz * vx - ux * vz;
                let nz = ux * vy - uy * vx;
                const nLen = Math.hypot(nx, ny, nz) || 1;
                nx /= nLen; ny /= nLen; nz /= nLen;

                const ndotl = Math.max(0, nx * LIGHT_DIR.x + ny * LIGHT_DIR.y + nz * LIGHT_DIR.z);
                const fresnel = Math.pow(1 - Math.min(1, Math.abs(nz)), 1.8);
                const spec = Math.pow(ndotl, 9) * (mat.metallic || 0.55) * 0.72;
                const shade = 0.25 + ndotl * 0.65;
                const rim = fresnel * 0.58;
                const avgDepth = (p0.depth + p1.depth + p2.depth) * 0.3333;

                drawTris.push({ p0, p1, p2, avgDepth, shade, spec, rim });
              }

              // 由远及近排序绘制
              drawTris.sort((a, b) => b.avgDepth - a.avgDepth);
              const fillAlpha = mat.fillOpacity != null ? mat.fillOpacity : (baseAlpha * 0.48);

              for (let t = 0; t < drawTris.length; t++) {
                const tri = drawTris[t];
                ctx.fillStyle = col.toShadedRgba(tri.shade, tri.spec, tri.rim, rimCol, fillAlpha);
                ctx.beginPath();
                ctx.moveTo(tri.p0.sx, tri.p0.sy);
                ctx.lineTo(tri.p1.sx, tri.p1.sy);
                ctx.lineTo(tri.p2.sx, tri.p2.sy);
                ctx.closePath();
                ctx.fill();
              }
            }

            // 绘制发光几何棱线
            ctx.save();
            const edgeCol = mat.edgeColor || col;
            if (mat.glow > 0) {
              ctx.shadowColor = edgeCol.toRgba(0.9);
              ctx.shadowBlur = mat.glow * pr;
            }
            ctx.lineWidth = (mat.linewidth || 1.25) * pr;
            ctx.strokeStyle = edgeCol.toRgba(baseAlpha);
            ctx.beginPath();
            for (let i = 0; i < edges.length; i += 2) {
              const p1 = projCache[edges[i]];
              const p2 = projCache[edges[i + 1]];
              if (!p1 || !p2) continue;
              ctx.moveTo(p1.sx, p1.sy);
              ctx.lineTo(p2.sx, p2.sy);
            }
            ctx.stroke();
            ctx.restore();
          }
        }

        if (node.children && node.children.length) {
          for (let c = 0; c < node.children.length; c++) {
            renderNode(node.children[c], curRx, curRy, curRz, curPx, curPy, curPz);
          }
        }
      };

      renderNode(scene, 0, 0, 0, 0, 0, 0);

      // 绘制前景 3D 联动 HUD 叠层（如冲击波环、准星刻度）
      if (scene.userData && typeof scene.userData.customForeground === 'function') {
        ctx.save();
        scene.userData.customForeground(ctx, W, H, pr);
        ctx.restore();
      }
    }
    dispose() {}
  }

  global.THREE = {
    REVISION: '160-local-lit',
    Color,
    Vector3,
    Float32BufferAttribute,
    BufferGeometry,
    WireframeGeometry,
    IcosahedronGeometry,
    OctahedronGeometry,
    BoxGeometry,
    TorusKnotGeometry,
    RingGeometry,
    Material,
    MeshBasicMaterial,
    LineBasicMaterial,
    PointsMaterial,
    Object3D,
    Scene,
    Group,
    Mesh,
    LineSegments,
    Points,
    GridHelper,
    PerspectiveCamera,
    Clock,
    WebGLRenderer
  };
})(typeof window !== 'undefined' ? window : globalThis);
